:root{--bg:#0b1220;--panel:#111a2c;--panel2:#0e1626;--line:#22304a;--text:#e6edf7;--muted:#8b9bb4;--dim:#64748f;--acc:#4cc2ff;--gold:#f5c542;--green:#3ddc84;--red:#ff6b6b;--chip:#1a2740}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
a{color:var(--acc)}
.skip{position:absolute;left:-999px;top:0;background:var(--acc);color:#04121f;padding:8px 12px;z-index:99}
.skip:focus{left:8px;top:8px}
main{max-width:1180px;margin:0 auto;padding:0 20px 64px}
.top{display:flex;justify-content:space-between;align-items:center;padding:18px 0 10px;border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:10px;font-size:22px;font-weight:800;letter-spacing:.2px}
.mark{width:14px;height:14px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 4px rgba(245,197,66,.18)}
.top-meta{display:flex;gap:8px;flex-wrap:wrap}
.pill{border:1px solid var(--line);border-radius:999px;padding:3px 10px;font-size:12px;color:var(--muted)}
.pill b{color:var(--text)}
.lede{display:grid;grid-template-columns:1.5fr 1fr;gap:24px;padding:20px 0 16px}
.lede h1{font-size:27px;line-height:1.2;margin:0 0 8px}
.lede p{margin:0;color:var(--muted);max-width:640px}
.lede p b{color:var(--text)}
.facts{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.fact{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px}
.fact span{display:block;font-size:12px;color:var(--muted)}
.fact b{display:block;font-size:19px;margin:1px 0}
.fact small{display:block;color:var(--dim);font-size:11px}
.spot{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:4px 0 18px}
