.card .iv{display:block;font-size:16px;font-weight:800;color:var(--gold)}
.card .sub{display:block;font-size:12px;color:var(--muted)}
.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:end;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:12px}
.field{display:flex;flex-direction:column;gap:4px}
.field label,.sub{font-size:12px;color:var(--muted)}
.field input,.field select{background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:7px;padding:7px 9px;font:inherit;min-width:0}
