caption{text-align:left;padding:10px 14px;color:var(--muted);font-size:13px}
th,td{padding:9px 12px;text-align:left;border-top:1px solid var(--line);white-space:nowrap}
thead th{border-top:0;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.4px}
th button{background:none;border:0;color:inherit;font:inherit;cursor:pointer;padding:0}
th button:hover{color:var(--text)}
td.num,.num{text-align:right;font-variant-numeric:tabular-nums}
tbody tr{cursor:pointer}
tbody tr:hover{background:#16223a}
tbody tr[data-selected="true"]{background:#1a2a47;box-shadow:inset 3px 0 0 var(--gold)}
.name b{display:block;font-size:14px}
.name .sub{font-size:12px;color:var(--muted)}
.implied .bar{height:5px;background:#1c2c49;border-radius:3px;margin-bottom:3px;overflow:hidden}
.implied .bar i{display:block;height:100%;background:var(--gold)}
.implied .num{font-weight:700;color:var(--gold)}
.pos{color:var(--green)}.neg{color:var(--red)}
.status{font-size:11px;font-weight:700;letter-spacing:.4px;border-radius:5px;padding:2px 7px;background:var(--chip);color:var(--acc)}
.status.early{background:#2a2113;color:var(--gold)}
.status.added{background:#12261c;color:var(--green)}
.empty{padding:36px;text-align:center}
.empty h2{margin:0 0 6px}
.empty p{color:var(--muted)}
.button{background:var(--acc);color:#04121f;border:0;border-radius:7px;padding:8px 14px;font:inherit;font-weight:700;cursor:pointer}
.drawer{position:fixed;top:0;right:0;bottom:0;width:460px;max-width:94vw;background:#0e1729;border-left:1px solid var(--line);overflow-y:auto;padding:20px 22px 40px;z-index:50;box-shadow:-16px 0 40px rgba(0,0,0,.5)}
.drawer h2{margin:2px 0 2px;font-size:22px}
.drawer .meta{color:var(--muted);font-size:13px;margin-bottom:12px}
.drawer h3{font-size:13px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted);margin:20px 0 8px;border-top:1px solid var(--line);padding-top:14px}
.close{float:right;background:none;border:1px solid var(--line);color:var(--muted);border-radius:7px;padding:4px 10px;cursor:pointer;font:inherit}
.kv{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.kv div{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:8px 10px}
.kv span{display:block;font-size:11px;color:var(--muted)}
.kv b{font-size:15px}
.formula{background:var(--panel2);border:1px solid var(--line);border-radius:8px;padding:10px 12px;font-size:13px;line-height:1.7}
.formula b{color:var(--gold)}
.steps{list-style:none;margin:0;padding:0;counter-reset:s}
.steps li{counter-increment:s;position:relative;padding:0 0 12px 34px;font-size:14px}
.steps li:before{content:counter(s);position:absolute;left:0;top:0;width:22px;height:22px;border-radius:50%;background:var(--chip);color:var(--acc);font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center}
.steps .cost{color:var(--muted);font-size:12px}
.peers{width:100%;font-size:13px}
.peers td,.peers th{padding:6px 8px}
.note{font-size:13px;color:var(--muted)}
.modelbox{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:16px 18px;margin-top:18px}
.modelbox h2{margin:0 0 6px;font-size:18px}
.modelbox p{color:var(--muted);margin:6px 0}
.modelbox code{background:var(--panel2);border:1px solid var(--line);border-radius:5px;padding:1px 6px;font-size:13px}
.mult{width:100%;font-size:13px}
.mult td,.mult th{padding:5px 8px}
.sandbox{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:10px}
.sandbox label{font-size:12px;color:var(--muted);display:block;margin-bottom:4px}
.sandbox input[type=range]{width:100%}
.sandbox output{color:var(--text);font-weight:700}
.sandbox .on{font-size:13px;color:var(--gold);font-weight:700}
.method{margin-top:18px;color:var(--muted);font-size:13px}
.method h2{color:var(--text);font-size:18px;margin:0 0 6px}
.method ul{margin:6px 0;padding-left:20px}
footer{margin-top:22px;color:var(--dim);font-size:12px}
@media (max-width:900px){.lede{grid-template-columns:1fr}.spot{grid-template-columns:repeat(2,1fr)}.sandbox{grid-template-columns:1fr}}
